patch -p0 <<'PATCH'
--- /dev/null
+++ tests/unit/cluster/cluster-shards.tcl
@@ -0,0 +1,108 @@
+proc cluster_shards_split_slots {masters replicas} {
+    R 0 cluster addslotsrange 0 1000 1002 5461
+    R 1 cluster addslotsrange 5462 10922
+    R 2 cluster addslotsrange 1001 1001 10923 16383
+}
+
+proc cluster_shard_for_node {reference node_id} {
+    foreach shard [R $reference cluster shards] {
+        foreach node [dict get $shard nodes] {
+            if {[dict get $node id] eq $node_id} {
+                return $shard
+            }
+        }
+    }
+    fail "Node $node_id not found in CLUSTER SHARDS on node $reference"
+}
+
+start_cluster 3 3 {tags {external:skip cluster}} {
+    set primary_id [R 0 cluster myid]
+    set replica_id [R 3 cluster myid]
+    set expected_slots {0 1000 1002 5461}
+
+    test "CLUSTER SHARDS reports split slot ranges on primaries and replicas" {
+        for {set ref 0} {$ref < 6} {incr ref} {
+            assert_equal $expected_slots [dict get [cluster_shard_for_node $ref $primary_id] slots]
+            assert_equal $expected_slots [dict get [cluster_shard_for_node $ref $replica_id] slots]
+        }
+        wait_for_condition 1000 50 {
+            [s -3 master_link_status] eq {up}
+        } else {
+            fail "Replica did not connect to its primary"
+        }
+    }
+
+    set paused_pid [srv 0 pid]
+    test "CLUSTER SHARDS retains slot ranges while the primary is failed" {
+        R 3 config set cluster-replica-no-failover yes
+        pause_process $paused_pid
+        for {set ref 1} {$ref < 6} {incr ref} {
+            wait_node_marked_fail $ref $primary_id
+            assert_equal $expected_slots [dict get [cluster_shard_for_node $ref $primary_id] slots]
+        }
+    }
+
+    test "CLUSTER SHARDS reports slot ranges after takeover of a failed primary" {
+        R 3 cluster failover takeover
+        for {set ref 1} {$ref < 6} {incr ref} {
+            wait_for_condition 1000 50 {
+                [dict get [cluster_get_node_by_id $ref $replica_id] slots] eq {0-1000 1002-5461}
+            } else {
+                fail "Node $ref did not learn the promoted primary's slots"
+            }
+
+            # The failed primary cannot announce its new role until it resumes.
+            set shard [cluster_shard_for_node $ref $primary_id]
+            set masters 0
+            foreach node [dict get $shard nodes] {
+                if {[dict get $node role] eq "master"} {
+                    incr masters
+                }
+                if {[dict get $node id] eq $primary_id} {
+                    assert_equal "fail" [dict get $node health]
+                }
+            }
+            assert_equal 2 $masters
+            assert_equal $expected_slots [dict get $shard slots]
+
+            # Repeated replies also exercise cleanup of the cached slot ranges.
+            assert_equal $expected_slots [dict get [cluster_shard_for_node $ref $replica_id] slots]
+        }
+    }
+
+    test "CLUSTER SHARDS retains slot ranges after the old primary rejoins" {
+        resume_process $paused_pid
+        R 3 config set cluster-replica-no-failover no
+        wait_for_condition 1000 50 {
+            [s 0 role] eq {slave}
+        } else {
+            fail "Old primary did not become a replica"
+        }
+        wait_for_cluster_propagation
+        for {set ref 0} {$ref < 6} {incr ref} {
+            assert_equal $expected_slots [dict get [cluster_shard_for_node $ref $primary_id] slots]
+        }
+    }
+} cluster_shards_split_slots
+
+start_server {overrides {cluster-enabled yes} tags {external:skip cluster}} {
+    test "CLUSTER SHARDS returns empty slots for a shard that owns no slots" {
+        set shards [r cluster shards]
+        assert_equal 1 [llength $shards]
+        set shard [lindex $shards 0]
+        assert_equal {} [dict get $shard slots]
+        assert_equal 1 [llength [dict get $shard nodes]]
+        assert_equal [r cluster myid] [dict get [lindex [dict get $shard nodes] 0] id]
+    }
+
+    test "CLUSTER SHARDS returns a single-slot range" {
+        r cluster addslots 1234
+        assert_equal {1234 1234} [dict get [lindex [r cluster shards] 0] slots]
+    }
+}
PATCH
./runtest --single unit/cluster/cluster-shards

